{
  "findings": [
    {
      "check_id": "CKV_AZURE_59",
      "title": "Ensure that Storage accounts disallow public access",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account does not explicitly disallow public access, which could lead to unintended data exposure."
    },
    {
      "check_id": "CKV_AZURE_33",
      "title": "Ensure Storage logging is enabled for Queue service for read, write and delete requests",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "Storage logging is not enabled, which could make it difficult to audit access and operations on the storage account."
    },
    {
      "check_id": "CKV_AZURE_44",
      "title": "Ensure Storage Account is using the latest version of TLS encryption",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account does not specify the minimum TLS version, which could allow weaker encryption protocols."
    },
    {
      "check_id": "CKV_AZURE_3",
      "title": "Ensure that 'enable_https_traffic_only' is enabled",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "HTTPS traffic is not enforced, which could allow insecure communication with the storage account."
    },
    {
      "check_id": "CKV_AZURE_206",
      "title": "Ensure that Storage Accounts use replication",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account uses LRS (Locally Redundant Storage), which does not provide geo-redundancy and could lead to data loss in case of a regional failure."
    },
    {
      "check_id": "CKV2_AZURE_40",
      "title": "Ensure storage account is not configured with Shared Key authorization",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "Shared Key authorization is enabled by default, which could lead to less secure access control."
    },
    {
      "check_id": "CKV2_AZURE_47",
      "title": "Ensure storage account is configured without blob anonymous access",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "Blob anonymous access is not explicitly disabled, which could allow unauthorized access to blob data."
    },
    {
      "check_id": "CKV2_AZURE_33",
      "title": "Ensure storage account is configured with private endpoint",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The storage account does not use a private endpoint, which could expose it to public network access."
    },
    {
      "check_id": "CKV2_AZURE_38",
      "title": "Ensure soft-delete is enabled on Azure storage account",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "Soft-delete is not enabled, which could lead to permanent data loss if data is accidentally deleted."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"notification_storage\" {\n  name                     = \"smartgridscada${random_string.suffix.result}\"\n  resource_group_name      = azurerm_resource_group.smart_grid_rg.name\n  location                 = azurerm_resource_group.smart_grid_rg.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"GRS\" # Changed from LRS to GRS for geo-redundancy\n  enable_https_traffic_only = true # Enforce HTTPS traffic only\n\n  allow_blob_public_access = false # Disallow public access to blobs\n  min_tls_version          = \"TLS1_2\" # Enforce the latest TLS version\n  shared_access_key_enabled = false # Disable Shared Key authorization\n\n  blob_properties {\n    delete_retention_policy {\n      days = 7 # Enable soft-delete with a retention period of 7 days\n    }\n  }\n\n  network_rules {\n    default_action = \"Deny\" # Deny public network access\n    bypass         = [\"AzureServices\"]\n  }\n\n  logging {\n    delete                = true # Enable logging for delete requests\n    read                  = true # Enable logging for read requests\n    write                 = true # Enable logging for write requests\n    version               = \"1.0\"\n    retention_policy_days = 7 # Retain logs for 7 days\n  }\n\n  private_endpoint_connection {\n    name = \"example-private-endpoint\"\n    private_service_connection {\n      is_manual_connection = false\n      private_connection_resource_id = azurerm_private_endpoint.example.id\n    }\n  }\n}",
  "fix_summary": "Enabled HTTPS traffic, disallowed public access, enforced TLS 1.2, enabled soft-delete, disabled Shared Key authorization, added logging, and configured private endpoint and geo-redundancy."
}
